(function(){
  var $=function(id){return document.getElementById(id)};
  var money=function(n){return n.toLocaleString(undefined,{maximumFractionDigits:0})};
  function calc(){
    var price=+$('price').value||0, down=+$('down').value||0;
    var rate=+$('rate').value||0, years=+$('years').value||0;
    var tax=+$('tax').value||0, ins=+$('ins').value||0;
    if(down>price) down=price;
    var loan=price-down, n=Math.round(years*12), r=rate/100/12;
    if(loan<=0||n<=0){ $('note').textContent='Enter a home price larger than the down payment.'; return; }
    // Standard amortisation. A zero rate is a plain division, not a divide by zero.
    var pi = r===0 ? loan/n : loan*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1);
    var interest = pi*n - loan;
    var pct = price>0 ? down/price*100 : 0;
    // Private mortgage insurance is normally charged until you hold 20% equity.
    var pmi = pct < 20 ? loan*0.005/12 : 0;
    var monthly = pi + tax/12 + ins/12 + pmi;
    $('total').textContent=money(monthly);
    $('pi').textContent=money(pi);
    $('interest').textContent=money(interest);
    var rows=[['Principal and interest',pi],['Property tax',tax/12],['Home insurance',ins/12]];
    if(pmi>0) rows.push(['Mortgage insurance (PMI)',pmi]);
    var html=rows.map(function(x){return '<div><span>'+x[0]+'</span><b>'+money(x[1])+'</b></div>'}).join('');
    html+='<div><span>Loan amount</span><b>'+money(loan)+'</b></div>';
    html+='<div><span>Down payment</span><b>'+pct.toFixed(1)+'%</b></div>';
    $('brk').innerHTML=html;
    $('note').textContent = pmi>0
      ? 'Your down payment is under 20%, so an estimated PMI charge is included. It usually stops once you reach 20% equity.'
      : 'A down payment of 20% or more avoids mortgage insurance, so none is included here.';
    if(window.WT) WT.resize();
  }
  ['price','down','rate','years','tax','ins'].forEach(function(id){
    $(id).addEventListener('input',calc);
  });
  $('go').addEventListener('click',calc);
  $('copy').addEventListener('click',function(){
    var ok=WT.copy('Total monthly payment: '+$('total').textContent+
      ' (principal and interest '+$('pi').textContent+')');
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy result'},1400);
  });
  calc();
})();
